"use client";

import { useEffect, useRef } from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";

interface ModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    children: React.ReactNode;
    width?: "sm" | "md" | "lg" | "xl";
}

export default function Modal({ isOpen, onClose, title, children, width = "md" }: ModalProps) {
    const modalRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === "Escape") onClose();
        };

        if (isOpen) {
            document.body.style.overflow = "hidden";
            window.addEventListener("keydown", handleEscape);
        }

        return () => {
            document.body.style.overflow = "unset";
            window.removeEventListener("keydown", handleEscape);
        };
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    const widthClasses = {
        sm: "max-w-md",
        md: "max-w-xl",
        lg: "max-w-3xl",
        xl: "max-w-5xl",
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center md:p-10 pointer-events-none">
            {/* Backdrop */}
            <div
                className="absolute inset-0 bg-black/60 backdrop-blur-md animate-in fade-in duration-500 pointer-events-auto"
                onClick={onClose}
            />

            {/* Modal Content - Square & Fullscreen mobile */}
            <div
                ref={modalRef}
                className={cn(
                    "relative w-full h-full md:h-auto bg-[var(--card)] rounded-none shadow-2xl overflow-hidden animate-in zoom-in-95 fade-in duration-500 border-0 md:border border-[var(--border)] pointer-events-auto flex flex-col transition-all",
                    widthClasses[width]
                )}
            >
                {/* Header - Square & Fluid */}
                <div className="px-6 py-5 border-b border-[var(--border)] flex items-center justify-between bg-[var(--background)]">
                    <div>
                        <h2 className="text-xl font-bold text-[var(--foreground)] tracking-tight leading-none">{title}</h2>
                        <p className="text-[9px] text-[var(--muted)] font-black uppercase tracking-widest mt-2 opacity-60">Delta Integrated System</p>
                    </div>
                    <button
                        onClick={onClose}
                        className="size-9 bg-[var(--accent)] hover:bg-[var(--accent)]/80 text-[var(--muted)] rounded-none transition-all flex items-center justify-center active:scale-90 border border-[var(--border)]"
                    >
                        <X size={18} />
                    </button>
                </div>

                {/* Body - Square & Scrollable */}
                <div className="flex-1 p-6 md:p-8 overflow-y-auto custom-scrollbar">
                    {children}
                </div>
            </div>
        </div>
    );
}
