"use client";

import { cn } from "@/lib/utils";
import { useSimulation } from "@/components/SimulationProvider";
import {
    Award,
    Search as SearchIcon,
    Wallet,
    Plus as PlusIcon,
    Bell as BellIcon,
    LogOut
} from "lucide-react";

import ThemeToggle from "./ThemeToggle";

export default function Header({ onOpenJourney }: { onOpenJourney?: () => void }) {
    const { currentUser, logout } = useSimulation();

    let tier = currentUser.level || 'Bronze';
    let tierColor = 'text-orange-700 bg-orange-500/10 border-orange-500/10';
    let tierIcon = <Award size={14} />;

    const normalizedLevel = (tier || '').toLowerCase();

    if (normalizedLevel === 'ouro') {
        tierColor = 'text-amber-700 bg-amber-500/10 border-amber-500/10';
        tierIcon = <Award size={14} className="text-amber-500" />;
    } else if (normalizedLevel === 'prata') {
        tierColor = 'text-slate-700 bg-slate-500/10 border-slate-500/10';
        tierIcon = <Award size={14} className="text-slate-400" />;
    }

    const renderAvatarContent = () => {
        if (currentUser.avatar) {
            return (
                <div
                    className="size-8 rounded-none bg-slate-200 bg-cover bg-center border border-white shadow-sm flex-shrink-0"
                    style={{ backgroundImage: `url('${currentUser.avatar}')` }}
                />
            );
        }
        const initials = currentUser.name.split(' ').map(n => n[0]).join('').substring(0, 2).toUpperCase();
        return (
            <div className="size-8 bg-primary/20 rounded-none flex items-center justify-center text-primary font-bold text-[10px] border border-white shadow-sm flex-shrink-0">
                {initials}
            </div>
        );
    };

    return (
        <header className="sticky top-0 z-40 bg-white/10 dark:bg-black/10 backdrop-blur-md px-4 py-3 border-b border-[var(--border)]">
            <div className="flex items-center justify-between max-w-full mx-auto w-full gap-4">
                <div className="flex items-center gap-4 flex-1">
                    <div className="relative w-full max-w-xl hidden md:block group">
                        <SearchIcon className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 transition-colors group-focus-within:text-primary" size={18} />
                        <input
                            className="w-full bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-none py-3 pl-12 pr-6 focus:outline-none focus:ring-4 focus:ring-primary/5 focus:border-primary text-xs font-medium transition-all placeholder:text-slate-400 shadow-sm"
                            placeholder="Pesquisar no painel..."
                            type="text"
                        />
                    </div>
                </div>

                <div className="flex items-center gap-4">
                    {/* Tier Badge - Dynamic */}
                    <div className={cn(
                        "flex items-center gap-2.5 px-5 py-2.5 rounded-none border transition-all duration-500 font-extrabold text-[10px] uppercase tracking-wider shadow-sm",
                        tierColor
                    )}>
                        {tierIcon}
                        <span>{tier}</span>
                    </div>

                    {/* Sales Value Display */}
                    <div className="hidden sm:flex items-center gap-3 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 px-5 py-2.5 rounded-none shadow-sm transition-all">
                        <Wallet size={16} className="text-slate-400" />
                        <span className="text-xs font-black tracking-tight">
                            {currentUser.sales_total.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })}
                        </span>
                    </div>

                    <button
                        onClick={onOpenJourney}
                        className="bg-primary text-white px-6 py-3 rounded-none font-black text-[10px] uppercase tracking-widest flex items-center gap-2 shadow-lg shadow-primary/20 hover:scale-105 active:scale-95 transition-all"
                    >
                        <PlusIcon size={16} />
                        <span className="hidden lg:inline">Novo Pedido</span>
                    </button>

                    <div className="flex items-center gap-3 ml-2">
                        <ThemeToggle className="p-2.5 rounded-none bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800" />

                        <button className="flex items-center justify-center p-3 rounded-none bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 text-slate-400 hover:text-primary transition-all relative">
                            <BellIcon size={20} />
                            <span className="absolute top-2 right-2 size-2 bg-primary rounded-none ring-2 ring-white dark:ring-slate-900"></span>
                        </button>

                        <div className="header-user-avatar cursor-pointer hover:scale-110 transition-all ml-1">
                            {renderAvatarContent()}
                        </div>
                    </div>
                </div>
            </div>

            {/* Mobile Search */}
            <div className="mt-4 md:hidden relative">
                <SearchIcon className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input
                    className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-none py-4 pl-14 pr-6 focus:ring-2 focus:ring-primary/20 text-xs font-bold"
                    placeholder="Pesquisar..."
                    type="text"
                />
            </div>
        </header>
    );
}
